        "title": "Нормализация и дублирование",
        "body": "Нормализация — способ организовать данные так, чтобы один факт не приходилось согласованно менять в десятках строк. Представим, что название магазина записано в каждой строке заказа. Если магазин переименуют, нужно обновить много заказов. Если часть строк пропустить, данные разойдутся.\n\nВ нормализованной схеме магазин хранится один раз в stores, а orders содержит store_id. Тогда название меняется в одном месте. При чтении можно соединить таблицы через JOIN и получить название рядом с заказом.\n\nНормализация помогает избежать аномалий обновления, вставки и удаления. Но это не правило «разбить всё на максимальное число таблиц». Решение зависит от смысла данных и нагрузки. В аналитике иногда создают денормализованные витрины, чтобы упростить чтение.",
