        "title": "Логический порядок обработки",
        "body": "SQL-запрос записывается в привычном порядке SELECT → FROM → WHERE → GROUP BY → HAVING → ORDER BY → LIMIT. Но логический порядок обработки отличается.\n\nУпрощённо сначала выполняется FROM и JOIN, затем WHERE убирает отдельные строки. После этого GROUP BY формирует группы, агрегаты вычисляются для групп, а HAVING отбрасывает ненужные группы. Затем формируется SELECT-список, выполняется DISTINCT, сортировка ORDER BY и ограничение LIMIT.\n\nЭто объясняет, почему алиас из SELECT обычно нельзя использовать в WHERE: на логическом этапе WHERE вычисляется раньше, чем формируется SELECT-список. В ORDER BY алиас обычно доступен, потому что сортировка выполняется позже.",
