        "example": "SELECT order_id, status, city\nFROM orders\nWHERE (status = 'paid' OR status = 'shipped')\n  AND city = 'Warsaw';",
        "note": "Не полагайся на память о приоритетах операторов в длинном условии. Ставь скобки вокруг логических групп.",
