        "title": "CASE: условная логика",
        "body": "CASE позволяет вернуть значение в зависимости от условий. PostgreSQL проверяет ветви WHEN по порядку и возвращает результат первой ветви, условие которой истинно. Если ни одна ветвь не подошла, используется ELSE; если ELSE нет, результатом будет NULL.\n\nCASE может использоваться в SELECT, ORDER BY, GROUP BY и агрегатах. Все ветви должны приводиться к совместимому типу результата. Это удобно для категорий, бизнес-меток и условной агрегации.\n\nПорядок условий важен. Если сначала поставить широкий диапазон, более узкая ветвь ниже может никогда не сработать. Располагай условия от специфичных к общим и проверяй границы.",
