        "title": "GROUP BY и зерно результата",
        "body": "GROUP BY делит входные строки на группы по значениям указанных столбцов. Агрегаты затем вычисляются отдельно внутри каждой группы. Если сгруппировать заказы по city, получится одна строка на город с количеством заказов и суммой.\n\nГруппировка меняет зерно результата. До неё строка могла представлять один заказ, после неё строка представляет один город. Поэтому в SELECT без агрегата можно выводить только столбцы группировки или выражения, однозначно зависящие от них.\n\nЕсли добавить второй столбец в GROUP BY, группы станут мельче: GROUP BY city, status даст отдельную строку для каждой пары город + статус. Количество строк результата обычно увеличится или останется прежним, но не уменьшится.",
