        "body": "WHERE фильтрует отдельные строки до группировки. HAVING фильтрует уже сформированные группы после вычисления агрегатов. Поэтому условие по обычному полю вроде city = 'Warsaw' обычно относится к WHERE, а условие COUNT(*) > 10 — к HAVING.\n\nЕсли можно отсеять строки до группировки, WHERE часто уменьшает объём работы. HAVING нужен, когда условие зависит от результата группы или когда требуется отобрать сами группы.\n\nНе путай HAVING с WHERE только потому, что оба выглядят как фильтры. Они действуют на разных уровнях: WHERE — строки, HAVING — группы.",
