        "title": "JOIN ... USING, NATURAL JOIN и LATERAL",
        "body": "USING — сокращённая запись ON, когда столбец связи называется одинаково в обеих таблицах. JOIN stores USING (store_id) эквивалентен условию по равенству store_id, но в результате общий столбец выводится один раз.\n\nNATURAL JOIN автоматически соединяет таблицы по всем одноимённым столбцам. Это опасно: добавление нового столбца с совпадающим именем может незаметно изменить условие соединения. В рабочих запросах обычно лучше явный ON или USING.\n\nLATERAL позволяет подзапросу в FROM ссылаться на столбцы источников, стоящих слева. Это удобно для поиска последнего события на каждую запись или ограниченного набора связанных строк. LATERAL особенно полезен вместе с LEFT JOIN, если нужно сохранить строки, для которых подзапрос ничего не нашёл.",
