        "title": "Fan-out: почему JOIN умножает строки",
        "body": "Fan-out — размножение строк при соединении источников с отношениями один-ко-многим или многие-ко-многим. Например, заказ с тремя позициями после JOIN будет представлен тремя строками. Если к позициям добавить таблицу платежей, где на заказ приходится два платежа, получится до шести комбинаций на заказ.\n\nЭто особенно опасно для метрик разных уровней. SUM по позициям может быть корректен после соединения с товарами, но SUM по платежам будет повторяться для каждой позиции. COUNT(DISTINCT order_id) может сохранить число заказов, но не исправит сумму платежей.\n\nБезопасный способ — агрегировать каждый источник до нужного зерна до соединения или использовать отдельные CTE для метрик заказов, позиций и платежей. Затем соединить уже подготовленные наборы, где на ключ приходится одна строка.",
        "simple": "Fan-out не ошибка SQL, а изменение числа строк. Ошибка — считать метрики, не учитывая новый уровень детализации.",
        "example": "WITH item_totals AS (\n  SELECT order_id, SUM(quantity * unit_price) AS items_total\n  FROM order_items\n  GROUP BY order_id\n),\npayment_totals AS (\n  SELECT order_id, SUM(amount) AS paid_total\n  FROM payments\n  GROUP BY order_id\n)\nSELECT o.order_id, i.items_total, p.paid_total\nFROM orders AS o\nLEFT JOIN item_totals AS i USING (order_id)\nLEFT JOIN payment_totals AS p USING (order_id);",
