        "body": "EXPLAIN ANALYZE действительно выполняет запрос. Для SELECT это обычно безопасно, но для UPDATE, DELETE, INSERT и некоторых DDL-команд выполнение может изменить данные. Перед экспериментом проверь текст запроса и при поддержке транзакционного отката выполняй его в BEGIN ... ROLLBACK. Не полагайся на откат для внешних эффектов: отправки сообщений, вызовов сторонних систем или действий триггеров с внешним эффектом.",
        "simple": "EXPLAIN ANALYZE не просто планирует запрос, а запускает его. Перед проверкой UPDATE или DELETE используй безопасную тестовую копию или транзакцию с ROLLBACK.",
        "example": "BEGIN;\nEXPLAIN ANALYZE\nUPDATE products\nSET price = price * 1.05\nWHERE product_id = 1;\nROLLBACK;",
